# Characters that separate words outside of quotes in ``COMP_LINE``.
_LINE_WHITESPACE = frozenset(" \t\r\n")
# Characters after which the shell starts replacing the cursor word.
_LINE_WORD_BREAKS = frozenset("=:")
# Characters escaped with a backslash when a candidate is written unquoted.
_LINE_ESCAPED = frozenset(" \t!\"#$&'()*;<>?[\\]`{|}~")
# Characters escaped with a backslash when written inside double quotes.
_LINE_DQUOTE_ESCAPED = frozenset('"\\$`')


def _utf8_length(char: str) -> int:
    """Number of bytes ``char`` occupies in the UTF-8 encoded line. Surrogate
    escapes produced when decoding the environment count as one byte.
    """
    try:
        return len(char.encode("utf-8", "surrogateescape"))
    except UnicodeEncodeError:
        return len(char.encode("utf-8", "surrogatepass"))


class _LineWords(t.NamedTuple):
    complete: list[str]
    incomplete: str
    kept: str
    quote: str | None


def _split_line(text: str) -> _LineWords:
    """Split the text before the cursor into complete words and the cursor
    word. Also report the part of the cursor word's value the shell keeps
    and the quote the cursor word ends in.
    """
    words: list[str] = []
    current: list[str] = []
    in_word = False
    quote: str | None = None
    quote_start = 0
    kept_length = 0
    index = 0
    length = len(text)

    while index < length:
        char = text[index]
        index += 1

        if quote == "'":
            if char == "'":
                quote = None
            else:
                current.append(char)
        elif quote == '"':
            if char == '"':
                quote = None
            elif char == "\\":
                if index < length:
                    escaped = text[index]
                    index += 1

                    if escaped not in _LINE_DQUOTE_ESCAPED:
                        current.append("\\")

                    current.append(escaped)
            else:
                current.append(char)
        elif char in _LINE_WHITESPACE:
            if in_word:
                words.append("".join(current))
                current = []
                in_word = False
        else:
            if not in_word:
                in_word = True
                kept_length = 0

            if char in "'\"":
                quote = char
                quote_start = len(current)
            elif char == "\\":
                if index < length:
                    current.append(text[index])
                    index += 1
            else:
                current.append(char)

                if char in _LINE_WORD_BREAKS:
                    kept_length = len(current)

    if not in_word:
        return _LineWords(words, "", "", None)

    incomplete = "".join(current)
    kept = incomplete[: quote_start if quote is not None else kept_length]
    return _LineWords(words, incomplete, kept, quote)


def _quote_line_suffix(value: str, quote: str | None) -> str:
    """Write ``value`` so the shell reads it back literally when it is
    inserted in the given quoting context.
    """
    if quote == "'":
        return value.replace("'", "'\\''")

    escaped = _LINE_DQUOTE_ESCAPED if quote == '"' else _LINE_ESCAPED
    return "".join(f"\\{char}" if char in escaped else char for char in value)


class LineComplete(ShellComplete):
    """Shell completion for Bash's ``complete -C`` protocol. The raw command
    line is read from ``COMP_LINE`` and the cursor byte offset from
    ``COMP_POINT``. One candidate is printed per line, quoted for the
    context the cursor word is typed in, relative to the part of the word
    the shell keeps.

    .. versionadded:: 8.6.0
    """

    name: t.ClassVar[str] = "line"
    source_template: t.ClassVar[str] = _SOURCE_LINE

    def _read_request(self) -> _LineWords:
        if "COMP_LINE" not in os.environ:
            raise CompletionRequestError(_("COMP_LINE is not set."))

        line = os.environ["COMP_LINE"]
        raw_point = os.environ.get("COMP_POINT", "")

        if not raw_point:
            return _split_line(line)

        if re.fullmatch(r"[0-9]+", raw_point) is None:
            raise CompletionRequestError(
                _(
                    "Invalid COMP_POINT value {value!r}: expected a"
                    " non-negative integer."
                ).format(value=raw_point)
            )

        point = int(raw_point)
        total = sum(_utf8_length(char) for char in line)

        if point > total:
            raise CompletionRequestError(
                ngettext(
                    "COMP_POINT {point} is past the end of COMP_LINE"
                    " ({length} byte).",
                    "COMP_POINT {point} is past the end of COMP_LINE"
                    " ({length} bytes).",
                    total,
                ).format(point=point, length=total)
            )

        offset = 0
        cut = 0

        for char in line:
            if offset >= point:
                break

            offset += _utf8_length(char)
            cut += 1

        if offset != point:
            raise CompletionRequestError(
                _("COMP_POINT {point} is inside a multi-byte character.").format(
                    point=point
                )
            )

        return _split_line(line[:cut])

    def get_completion_args(self) -> tuple[list[str], str]:
        request = self._read_request()
        return request.complete[1:], request.incomplete

    def format_completion(self, item: CompletionItem[t.Any]) -> str:
        return str(item.value)

    def complete(self) -> str:
        request = self._read_request()

        # The first complete word is the program name. Without it there is
        # nothing to resolve.
        if not request.complete:
            return ""

        args = request.complete[1:]
        incomplete = request.incomplete
        ctx = _resolve_context(self.cli, self.ctx_args, self.prog_name, args)

        # Values completed for ``--opt=value`` are bare values, but the shell
        # replaces part of the whole word, so restore the ``--opt=`` part.
        word_prefix = ""

        if "=" in incomplete and _start_of_option(ctx, incomplete):
            name = incomplete.partition("=")[0]
            word_prefix = f"{name}="

        obj, value_incomplete = _resolve_incomplete(ctx, args, incomplete)
        lines: list[str] = []
        seen: set[str] = set()

        for item in obj.shell_complete(ctx, value_incomplete):
            if item.type != "plain":
                continue

            value = self.format_completion(item)

            if "\n" in value or "\r" in value:
                continue

            word = f"{word_prefix}{value}"

            if not word.startswith(request.kept):
                continue

            rendered = _quote_line_suffix(word[len(request.kept) :], request.quote)

            if not rendered or rendered in seen:
                continue

            seen.add(rendered)
            lines.append(f"{rendered}\n")

        return "".join(lines)


